def parse(text: str) -> list[list[str]]:
    """Parse CSV text into a list of records, each a list of field strings."""
    rows = []
    i = 0
    n = len(text)

    while i < n:
        row = []
        # Parse one row
        while True:
            if i >= n:
                # End of input - if we were collecting a field, add empty
                if not row:
                    break
                row.append("")
                break

            # Check if field starts with a quote
            if text[i] == '"':
                # Quoted field
                i += 1  # skip opening quote
                field = []
                while i < n:
                    if text[i] == '"':
                        if i + 1 < n and text[i + 1] == '"':
                            # Escaped quote
                            field.append('"')
                            i += 2
                        else:
                            # End of quoted field
                            i += 1  # skip closing quote
                            break
                    else:
                        field.append(text[i])
                        i += 1
                row.append("".join(field))
            else:
                # Unquoted field - read until comma or end of line
                field = []
                while i < n and text[i] != ',' and text[i] != '\n' and text[i] != '\r':
                    field.append(text[i])
                    i += 1
                row.append("".join(field))

            # After field, check what's next
            if i >= n:
                break
            elif text[i] == ',':
                i += 1  # skip comma, continue to next field
                # If comma is at end of file, we need an empty trailing field
                if i >= n:
                    row.append("")
                    break
            elif text[i] == '\r':
                # CRLF or CR line ending
                i += 1
                if i < n and text[i] == '\n':
                    i += 1  # skip LF
                break
            elif text[i] == '\n':
                i += 1  # skip LF
                break

        # Only add non-empty rows (but handle empty input case)
        if row or (not rows and text == ""):
            rows.append(row)

    # Handle empty input
    if text == "" or text.strip() == "":
        return []

    return rows

