"""Small CSV parsing helper used by the reporting scripts."""


def parse(text: str) -> list[list[str]]:
    """Parse CSV text into a list of records, each a list of field strings."""
    rows = []
    if not text:
        return rows

    i = 0
    length = len(text)

    while i < length:
        row, i = _parse_row(text, i)
        if row is not None:
            rows.append(row)

    return rows


def _parse_row(text: str, start: int) -> tuple[list[str] | None, int]:
    """Parse a single row starting at position start. Returns (row, next_position) or (None, start)."""
    fields = []
    length = len(text)
    i = start

    while i < length:
        # Check for end of row (newline)
        if text[i] == '\n':
            i += 1
            break
        if text[i] == '\r':
            # Handle \r\n or standalone \r
            if i + 1 < length and text[i + 1] == '\n':
                i += 2
            else:
                i += 1
            break

        # Parse field
        field, i = _parse_field(text, i)
        fields.append(field)

        # Check for comma separator
        if i < length and text[i] == ',':
            i += 1
            # Handle trailing comma (empty field at end)
            if i >= length or text[i] == '\n' or text[i] == '\r':
                fields.append('')
                if i < length and text[i] == '\n':
                    i += 1
                elif i < length and text[i] == '\r':
                    if i + 1 < length and text[i + 1] == '\n':
                        i += 2
                    else:
                        i += 1
                break
        elif i >= length:
            # End of input
            break

    if not fields and i == start:
        return None, start

    return fields, i


def _parse_field(text: str, start: int) -> tuple[str, int]:
    """Parse a single field starting at position start. Returns (field_value, next_position)."""
    length = len(text)
    i = start

    if i < length and text[i] == '"':
        # Quoted field
        return _parse_quoted_field(text, i)
    else:
        # Unquoted field - read until comma or newline
        return _parse_unquoted_field(text, i)


def _parse_quoted_field(text: str, start: int) -> tuple[str, int]:
    """Parse a quoted field starting with a quote at position start."""
    length = len(text)
    i = start + 1  # Skip opening quote
    chars = []

    while i < length:
        if text[i] == '"':
            # Check for escaped quote ""
            if i + 1 < length and text[i + 1] == '"':
                chars.append('"')
                i += 2
            else:
                # End of quoted field
                i += 1  # Skip closing quote
                # Skip any characters until comma or newline (permissive parsing)
                while i < length and text[i] != ',' and text[i] != '\n' and text[i] != '\r':
                    i += 1
                return ''.join(chars), i
        else:
            chars.append(text[i])
            i += 1

    # Reached end of input without closing quote - return what we have
    return ''.join(chars), i


def _parse_unquoted_field(text: str, start: int) -> tuple[str, int]:
    """Parse an unquoted field starting at position start."""
    length = len(text)
    i = start
    chars = []

    while i < length:
        ch = text[i]
        if ch == ',' or ch == '\n' or ch == '\r':
            break
        chars.append(ch)
        i += 1

    return ''.join(chars), i

