        self.assertEqual(convert("100", "EUR", "USD"), Decimal("108.50"))
        self.assertEqual(convert("19.99", "EUR", "GBP"), Decimal("17.09"))

    def test_to_eur(self):
        self.assertEqual(convert("54.99", "USD", "EUR"), Decimal("50.68"))
