            i += 1  # skip comma
            saw_comma = True
        else:
            # End of row: handle line endings
            if i < n and text[i] == '\r' and i + 1 < n and text[i + 1] == '\n':
                i += 2  # CRLF
            elif i < n and text[i] == '\n':
                i += 1  # LF
            elif i < n and text[i] == '\r':
                i += 1  # CR alone
            else:
                # End of input without newline
                pass
            return fields, i

    # Reached end of input
    # If we ended with a comma, we need to add an empty field
    if saw_comma:
        fields.append('')
    return fields, i


def _parse_field(text: str, start: int, n: int) -> tuple[str, int]:
    """Parse a single field starting at position start. Returns (field_value, next_position)."""
    i = start

    if i < n and text[i] == '"':
        # Quoted field
        return _parse_quoted_field(text, i, n)
    else:
        # Unquoted field - read until comma or line ending
        return _parse_unquoted_field(text, i, n)


def _parse_quoted_field(text: str, start: int, n: int) -> tuple[str, int]:
    """Parse a quoted field. Opening quote is at position start."""
    i = start + 1  # skip opening quote
    result = []

    while i < n:
        if text[i] == '"':
            if i + 1 < n and text[i + 1] == '"':
                # Escaped quote
                result.append('"')
                i += 2
            else:
                # Closing quote
                i += 1  # skip closing quote
                return ''.join(result), i
        else:
            result.append(text[i])
            i += 1

    # Reached end of input without closing quote - return what we have
    return ''.join(result), i


def _parse_unquoted_field(text: str, start: int, n: int) -> tuple[str, int]:
    """Parse an unquoted field. Returns (field_value, next_position)."""
    i = start
    result = []

    while i < n:
        c = text[i]
        if c == ',' or c == '\n' or c == '\r':
            break
        result.append(c)
        i += 1

    return ''.join(result), i

