"""Small CSV parsing helper used by the reporting scripts."""


def parse(text: str) -> list[list[str]]:
    """Parse CSV text into a list of records, each a list of field strings."""
    rows = []
    i = 0
    n = len(text)

    while i < n:
        row = []
        # Parse one row
        while True:
            if i >= n:
                # End of input - add empty field if we were in the middle of a row
                if not row:
                    break
                row.append("")
                break

            if text[i] == '"':
                # Quoted field
                i += 1  # skip opening quote
                field = []
                while i < n:
                    if text[i] == '"':
                        if i + 1 < n and text[i + 1] == '"':
                            # Escaped quote
                            field.append('"')
                            i += 2
                        else:
                            # End of quoted field
                            i += 1  # skip closing quote
                            break
                    else:
                        field.append(text[i])
                        i += 1
                row.append("".join(field))
            else:
                # Unquoted field - read until comma or line ending
                field = []
                while i < n and text[i] != ',' and text[i] != '\n' and text[i] != '\r':
                    field.append(text[i])
                    i += 1
                row.append("".join(field))

            if i >= n:
                break

            if text[i] == ',':
                i += 1  # skip comma, continue to next field
                # If this is the last character and we just finished a row, 
                # we need to add an empty trailing field
                if i >= n:
                    row.append("")
                    break
                continue
            elif text[i] == '\r':
                # CRLF or CR line ending
                i += 1
                if i < n and text[i] == '\n':
                    i += 1  # skip LF
                break
            elif text[i] == '\n':
                i += 1  # skip LF
                break

        # Skip completely empty lines (but not lines that produced a row)
        if row == [""]:
            continue

        rows.append(row)

    return rows

