"""Original implementation of count_spans_with_sum_between, kept for speed comparisons in bench.py."""


def count_spans_with_sum_between(values, lo, hi):
    count = 0
    n = len(values)
    for i in range(n):
        for j in range(i + 1, n + 1):
            if lo <= sum(values[i:j]) <= hi:
                count += 1
    return count

