        raise AssertionError(f"got {got!r}, expected {want!r}")


def test_example():
    check(count_spans_with_sum_between([1, -2, 3, 1], 1, 2), 5)


def test_empty_input():
    check(count_spans_with_sum_between([], -5, 5), 0)


def test_single_value():
    check(count_spans_with_sum_between([5], 5, 5), 1)
    check(count_spans_with_sum_between([5], 6, 9), 0)


def test_every_span_counts():
